        (
          delimited = :erlang.map_get(:turnover, msg)
          delimited_prefix = Protox.Encode.encode_string_prefix(delimited)
        )

        {["J", delimited_prefix, delimited | acc],
         acc_size + 1 + (byte_size(delimited_prefix) + byte_size(delimited))}
      end
    end

    defp encode_volume({acc, acc_size}, msg) do
      if :erlang.map_get(:volume, msg) == 0 do
        {acc, acc_size}
      else
        value_bytes =
          Protox.Varint.encode(
            :erlang.band(:erlang.map_get(:volume, msg), 18_446_744_073_709_551_615)
          )

        {["@", value_bytes | acc], acc_size + 1 + byte_size(value_bytes)}
      end
    end

    defp encode_timestamp({acc, acc_size}, msg) do
      if :erlang.map_get(:timestamp, msg) == 0 do
        {acc, acc_size}
      else
        value_bytes =
          Protox.Varint.encode(
            :erlang.band(:erlang.map_get(:timestamp, msg), 18_446_744_073_709_551_615)
          )

        {["8", value_bytes | acc], acc_size + 1 + byte_size(value_bytes)}
      end
    end

    defp encode_low({acc, acc_size}, msg) do
      if :erlang.map_get(:low, msg) == "" do
        {acc, acc_size}
      else
        (
          delimited = :erlang.map_get(:low, msg)
          delimited_prefix = Protox.Encode.encode_string_prefix(delimited)
        )

        {["2", delimited_prefix, delimited | acc],
         acc_size + 1 + (byte_size(delimited_prefix) + byte_size(delimited))}
      end
    end

    defp encode_high({acc, acc_size}, msg) do
      if :erlang.map_get(:high, msg) == "" do
        {acc, acc_size}
      else
        (
          delimited = :erlang.map_get(:high, msg)
          delimited_prefix = Protox.Encode.encode_string_prefix(delimited)
        )

        {["*", delimited_prefix, delimited | acc],
         acc_size + 1 + (byte_size(delimited_prefix) + byte_size(delimited))}
      end
    end

    defp encode_open({acc, acc_size}, msg) do
      if :erlang.map_get(:open, msg) == "" do
        {acc, acc_size}
      else
        (
          delimited = :erlang.map_get(:open, msg)
          delimited_prefix = Protox.Encode.encode_string_prefix(delimited)
        )

        {["\"", delimited_prefix, delimited | acc],
         acc_size + 1 + (byte_size(delimited_prefix) + byte_size(delimited))}
      end
    end

    defp encode_prev_close({acc, acc_size}, msg) do
      if :erlang.map_get(:prev_close, msg) == "" do
        {acc, acc_size}
      else
        (
          delimited = :erlang.map_get(:prev_close, msg)
          delimited_prefix = Protox.Encode.encode_string_prefix(delimited)
        )

        {["\x1A", delimited_prefix, delimited | acc],
         acc_size + 1 + (byte_size(delimited_prefix) + byte_size(delimited))}
      end
    end

    defp encode_last_done({acc, acc_size}, msg) do
      if :erlang.map_get(:last_done, msg) == "" do
        {acc, acc_size}
      else
        (
          delimited = :erlang.map_get(:last_done, msg)
          delimited_prefix = Protox.Encode.encode_string_prefix(delimited)
        )

        {["\x12", delimited_prefix, delimited | acc],
         acc_size + 1 + (byte_size(delimited_prefix) + byte_size(delimited))}
      end
    end

    defp encode_symbol({acc, acc_size}, msg) do
      if :erlang.map_get(:symbol, msg) == "" do
        {acc, acc_size}
      else
        (
          delimited = :erlang.map_get(:symbol, msg)
          delimited_prefix = Protox.Encode.encode_string_prefix(delimited)
        )

        {["\n", delimited_prefix, delimited | acc],
         acc_size + 1 + (byte_size(delimited_prefix) + byte_size(delimited))}
      end
    end

    (
      defp encode_diagnose!(%{__struct__: __MODULE__} = msg) do
        Protox.Encode.find_invalid_field!(msg, [
          {:option_extend, &encode_option_extend/2, Longbridge.Quote.V1.OptionExtend},
          {:trade_status, &encode_trade_status/2, nil},
          {:turnover, &encode_turnover/2, nil},
          {:volume, &encode_volume/2, nil},
          {:timestamp, &encode_timestamp/2, nil},
          {:low, &encode_low/2, nil},
          {:high, &encode_high/2, nil},
          {:open, &encode_open/2, nil},
          {:prev_close, &encode_prev_close/2, nil},
          {:last_done, &encode_last_done/2, nil},
          {:symbol, &encode_symbol/2, nil}
        ])
      end

      defp encode_diagnose!(_malformed_input), do: :ok
    )

    defp encode_unknown_fields(acc, msg) do
      Protox.Encode.encode_unknown_fields(acc, :erlang.map_get(:__uf__, msg))
    end
  )

  (
    (
      @spec decode(binary()) :: {:ok, t()} | {:error, any()}
      def decode(bytes) do
        {:ok, decode!(bytes)}
      rescue
        e in [Protox.DecodingError, Protox.IllegalTagError, Protox.RequiredFieldsError] ->
          {:error, e}
      end

      (
        @spec decode!(binary()) :: t() | no_return()
        def decode!(bytes), do: parse_key_value(bytes, __struct__())
      )
    )

    (
      @spec parse_key_value(binary(), struct()) :: struct()
      defp parse_key_value(<<>>, msg) do
        case :erlang.map_get(:__uf__, msg) do
          [_first, _second | _tail] = values -> %{msg | __uf__: :lists.reverse(values)}
          _empty_or_single -> msg
        end
      end

      defp parse_key_value(bytes, msg) do
        case bytes do
          <<_tag::5, 3::3, _rest::binary>> ->
            raise Protox.DecodingError.new(bytes, "invalid wire type 3")

          <<_tag::5, 4::3, _rest::binary>> ->
            raise Protox.DecodingError.new(bytes, "invalid wire type 4")

          <<_tag::5, 6::3, _rest::binary>> ->
            raise Protox.DecodingError.new(bytes, "invalid wire type 6")

          <<_tag::5, 7::3, _rest::binary>> ->
            raise Protox.DecodingError.new(bytes, "invalid wire type 7")

          <<0::5, _wire_type::3, _rest::binary>> ->
            raise %Protox.IllegalTagError{}

          <<"Z", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)

            msg = %{
              msg
              | option_extend:
                  case :erlang.map_get(:option_extend, msg) do
                    nil ->
                      Longbridge.Quote.V1.OptionExtend.decode!(delimited)

                    previous_value ->
                      Protox.MergeMessage.merge(
                        previous_value,
                        Longbridge.Quote.V1.OptionExtend.decode!(delimited)
                      )
                  end
            }

            parse_key_value(rest, msg)

          <<"P", 0::1, varint_value::7, rest::binary>> ->
            value = Longbridge.Quote.V1.TradeStatus.decode(varint_value)
            msg = %{msg | trade_status: value}
            parse_key_value(rest, msg)

          <<"P", bytes::binary>> ->
            {value, rest} = Protox.Decode.parse_enum(bytes, Longbridge.Quote.V1.TradeStatus)
            msg = %{msg | trade_status: value}
            parse_key_value(rest, msg)

          <<"J", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)
            msg = %{msg | turnover: Protox.Decode.validate_string!(delimited)}
            parse_key_value(rest, msg)

          <<"@", 0::1, varint_value::7, rest::binary>> ->
            value = varint_value
            msg = %{msg | volume: value}
            parse_key_value(rest, msg)

          <<"@", bytes::binary>> ->
            {value, rest} = Protox.Decode.parse_int64(bytes)
            msg = %{msg | volume: value}
            parse_key_value(rest, msg)

          <<"8", 0::1, varint_value::7, rest::binary>> ->
            value = varint_value
            msg = %{msg | timestamp: value}
            parse_key_value(rest, msg)

          <<"8", bytes::binary>> ->
            {value, rest} = Protox.Decode.parse_int64(bytes)
            msg = %{msg | timestamp: value}
            parse_key_value(rest, msg)

          <<"2", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)
            msg = %{msg | low: Protox.Decode.validate_string!(delimited)}
            parse_key_value(rest, msg)

          <<"*", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)
            msg = %{msg | high: Protox.Decode.validate_string!(delimited)}
            parse_key_value(rest, msg)

          <<"\"", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)
            msg = %{msg | open: Protox.Decode.validate_string!(delimited)}
            parse_key_value(rest, msg)

          <<"\x1A", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)
            msg = %{msg | prev_close: Protox.Decode.validate_string!(delimited)}
            parse_key_value(rest, msg)

          <<"\x12", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)
            msg = %{msg | last_done: Protox.Decode.validate_string!(delimited)}
            parse_key_value(rest, msg)

          <<"\n", bytes::binary>> ->
            {delimited, rest} = Protox.Decode.parse_delimited(bytes)
            msg = %{msg | symbol: Protox.Decode.validate_string!(delimited)}
            parse_key_value(rest, msg)

          <<bytes::binary>> ->
            {tag, wire_type, rest} = Protox.Decode.parse_key(bytes)
            {value, rest} = Protox.Decode.parse_unknown(tag, wire_type, rest)
            msg = %{msg | __uf__: [value | :erlang.map_get(:__uf__, msg)]}
            parse_key_value(rest, msg)
        end
      end
    )
  )

  (
    @spec unknown_fields(struct()) :: [{non_neg_integer(), Protox.Types.tag(), binary()}]
    def unknown_fields(msg), do: msg.__uf__

    @spec unknown_fields_name() :: :__uf__
    def unknown_fields_name(), do: :__uf__

    @spec clear_unknown_fields(struct) :: struct
    def clear_unknown_fields(msg), do: struct!(msg, __uf__: [])
  )

  (
    @spec default(atom()) ::
            {:ok, Protox.Scalar.scalar_default_value_type()}
            | {:error, :no_such_field | :no_default_value}
    def default(field_name), do: Protox.MessageSchema.default(@schema, field_name)
  )
end
